
(()=>{
  'use strict';
  const frame=document.getElementById('tjktQuestFrame');
  const reward=document.getElementById('tjktQuestRewardStatus');
  if(!frame)return;
  const source64="";
  let loaded=false;
  const readUser=()=>{let name=String(window.netquestCurrentUser||'');try{name=localStorage.getItem('nq_demo_user')||name}catch(e){}return name.trim()};
  const syncUser=()=>{if(!frame.contentWindow)return;const name=readUser();if(name)try{frame.contentWindow.postMessage({type:'netquest-tjktquest-user',name},'*')}catch(e){}};
  const scheduleUserSync=()=>[0,180,600].forEach(delay=>setTimeout(syncUser,delay));
  const load=()=>{
    if(loaded)return;
    loaded=true;
    try{
      const bytes=Uint8Array.from(atob(source64),c=>c.charCodeAt(0));
      frame.srcdoc=new TextDecoder('utf-8').decode(bytes);
    }catch(error){
      loaded=false;
      if(reward)reward.textContent='TJKT Quest gagal dimuat. Buka ulang halaman NEXORA dan coba lagi.';
      console.error('[NEXORA] TJKT Quest load error:',error);
    }
  };
  document.querySelectorAll('[data-gamepanel="tjktquest"]').forEach(button=>button.addEventListener('click',()=>{load();scheduleUserSync()}));
  frame.addEventListener('load',()=>{scheduleUserSync();if(typeof window.netquestTJKTQuestRewarded==='function'&&window.netquestTJKTQuestRewarded()&&reward)reward.textContent='✓ Bonus +20 XP sudah pernah diterima pada akun ini.'});
  window.addEventListener('netquest:account-changed',scheduleUserSync);
  window.addEventListener('message',event=>{
    if(event.source!==frame.contentWindow||!event.data||typeof event.data!=='object')return;
    const data=event.data;
    if(data.type==='netquest-tjktquest-user-ready'){return;}
    if(data.type==='netquest-tjktquest-resize'){
      const height=Number(data.height);
      if(Number.isFinite(height)){const next=Math.max(1100,Math.min(4200,Math.ceil(height+28)));const current=frame.getBoundingClientRect().height;if(Math.abs(next-current)>10)frame.style.height=next+'px';}
      return;
    }
    if(data.type==='netquest-tjktquest-completed'){
      let activeName='';try{activeName=localStorage.getItem('nq_demo_user')||window.netquestCurrentUser||''}catch(e){activeName=window.netquestCurrentUser||''}
      const player=String(data.player||'').trim().toLocaleLowerCase('id');
      const active=String(activeName||'').trim().toLocaleLowerCase('id');
      if(data.complete===true){
        if(player&&active&&player!==active){if(reward)reward.textContent='Sesi selesai untuk '+data.player+'. Bonus tidak diberikan karena akun NEXORA yang aktif sudah berganti.';return;}
        const awarded=typeof window.netquestAwardTJKTQuest==='function'&&window.netquestAwardTJKTQuest();
        if(reward)reward.textContent=awarded?'✓ Tantangan selesai! Bonus +20 XP berhasil ditambahkan ke akun NEXORA.':(window.netquestTJKTQuestRewarded&&window.netquestTJKTQuestRewarded()?'✓ Tantangan selesai. Bonus +20 XP untuk game ini sudah pernah diterima.':'Tantangan selesai.');
      }else if(reward){
        reward.textContent='Sesi berakhir sebelum seluruh soal selesai. Coba lagi untuk membuka bonus +20 XP.';
      }
    }
  });
  const notifyQuestVisibility=visible=>{try{frame.contentWindow?.postMessage({type:'netquest-tjktquest-parent-visibility',visible},'*')}catch(e){}};
  document.addEventListener('click',event=>{
    const nav=event.target.closest('[data-v]');
    if(nav&&nav.dataset.v!=='game')notifyQuestVisibility(false);
    const panel=event.target.closest('[data-gamepanel]');
    if(panel)notifyQuestVisibility(panel.dataset.gamepanel==='tjktquest');
  });
  document.addEventListener('visibilitychange',()=>{if(document.hidden)notifyQuestVisibility(false)});
  // Prepare the module as soon as the game view is selected; it remains lazy-loaded
  // so the initial NEXORA dashboard stays fast.
})();
